import { NextRequest, NextResponse } from "next/server";
import { synthesizeSpeech, SpeechUnavailableError } from "@/lib/speech";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/** Returns a WAV file generated by the local system voice. */
export async function POST(req: NextRequest) {
  const body = (await req.json().catch(() => ({}))) as {
    text?: string;
    voice?: string;
    rate?: number;
  };
  try {
    const speech = await synthesizeSpeech({
      text: body.text || "",
      voice: body.voice,
      rate: body.rate,
    });
    return new NextResponse(new Uint8Array(speech.buffer), {
      headers: {
        "content-type": speech.mime,
        "content-disposition": `attachment; filename="${speech.filename}"`,
        "x-speech-engine": speech.engine,
        "cache-control": "no-store",
      },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return NextResponse.json(
      { error: message },
      { status: error instanceof SpeechUnavailableError ? 503 : 400 }
    );
  }
}
